INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Abronia latifolia', 'Sand Verbena', '4', 'Bats, Bees, Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '6 in', '7 ft', 'Fast', 'Summer Deciduous', 'Yellow', 'Summer, Spring, Fall', null, 'Full Sun', 'Fast', 'Very Low', 'Max 1x / week once established', null, 'Rarely Available', '<p>Coastal plants such as other Verbena species - Red Sand Verbena (Abronia maritima), Pink Sand Verbena (Abronia umbellata), Common Yarrow (Achillea millefolium), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Saltbush species (<a href="/search/?plant=Atriplex%20(Genus)">Atriplex spp.</a>), Morning-glory species (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Beach Evening Primrose (Camissoniopsis cheiranthifolia), Sandcarpet (Cardionema ramosissimum), Croton (Croton californicus), Seaside Daisy species (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Buckwheat species (Eriogonum latifolium, Eriogonum parvifolium), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Wallflower (<a href="/search/?plant=Erysimum%20(Genus)">Erysimum spp.</a>), Beach Strawberry (Fragaria chiloensis), Coastal Gumplant (Grindelia stricta), Silky Beach Pea (Lathyrus littoralis), Dunedelion (Malacothrix incana), Hummingbird Sage (Salvia spathacea), Penstemon species, Sand Dune Bluegrass (Poa douglasii). Emergent shrubs may be present at low cover including Coyote Bush (Baccharis pilularis), California Goldenbush (Ericameria ericoides), Lupine species (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>).</p>', null, 'Coastal Scrub', 'Coastal Sage Scrub, Coastal Strand', 'Tolerates cold to 20 °F', null, 'Coarse to fine-textured sands; very loose and free of organic debris', 'Sand', '5.0 - 7.0', 'Tolerates saline soil.', null, 'Dunes, coastal strand', '0', '2029', '13.029999999999999', '110.94', '<p>Requires fast draining soil. Prefers sun. Likes sandy soils.</p>', null, null, '6', '6', '84', '84', 'Verbena, Sand', 'Sand-verbena,Coastal Sand Verbena,Yellow Sand Verbena,Yellow Sand-verbena', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Abronia+latifolia', 'https://calscape.org/Abronia-latifolia-%28Sand-Verbena%29', 'https://calscape.org/storage/app/media/qr/Abronia-latifolia-%28Sand-Verbena%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Abronia maritima', 'Red Sand Verbena', '4', 'Bees, Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '5 in', '2 - 6 ft', null, 'Evergreen', 'Pink, Purple, Red', 'Winter, Spring, Summer, Fall', null, 'Full Sun', 'Fast', 'Very Low', 'Max 1x / month once established', null, 'Commonly Available', 'Plant with other dune wildflowers and shrubs such as Dune Bush Lupine (Lupinus chamissonis), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Sand-loving Wallflower (Erysimum ammophilum), Sandcarpet (Cardionema ramosissimum), and Coastal Buckbrush (Ceanothus cuneatus var. ramulosus).', null, 'Coastal Scrub', 'Coastal Strand', 'Tolerates cold to 30&deg; F', '17*, 24*', 'Prefers beach sand', 'Loamy Sand, Sand', '5 - 7', 'Tolerates saline soil.', null, 'Sand dunes along the coast.', '0', '1397', '7.6900000000000004', '41.280000000000001', 'Requires fast draining soil. Prefers sun. Likes sandy soils.', null, 'For propagating by seed: No treatment. (Emery and Frey 1971). Collect seeds from seed heads after they have dried on the plant. Sow directly in the sand after in Fall or after last frost.', '5', '5', '24', '72', 'Verbena, Red Sand', 'Red Sand-verbena,Sticky Sand-verbena', null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Abronia+maritima', 'https://calscape.org/Abronia-maritima-%28Red-Sand-Verbena%29', 'https://calscape.org/storage/app/media/qr/Abronia-maritima-%28Red-Sand-Verbena%29.png');
