INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Aconitum columbianum', 'Columbian Monkshood', '2', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '1 - 5 ft', null, 'Moderate', null, 'Blue, Purple, Yellow, White', 'Summer', null, 'Full Sun, Partial Shade', 'Medium', 'Low, Moderate, High', null, null, 'Rarely Available', null, null, 'Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', null, '1, 2, 3, 4*, 5*, 6*, 7, 14, 15, 16, 17, 18', 'Prefers moist, fertile soil', null, null, null, null, 'Streambanks and meadows', '1231', '12022', '5.4199999999999999', '154.74000000000001', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 5.4-7.2. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Aconitum columbianum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 50 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of full shade. Prefers sun or part shade. Likes stream banks.', null, 'For propagating by seed:  No treatment. (Emery and Frey 1971). 2 mos. stratification may improve germination ( Plants of the Southwest 1984 ).', '12', '60', null, null, 'Monkshood, Columbian', 'Columbia Monkshood,Monkshood (columbian),Western Monkshood', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Aconitum+columbianum', 'https://calscape.org/Aconitum-columbianum-%28Columbian-Monkshood%29', 'https://calscape.org/storage/app/media/qr/Aconitum-columbianum-%28Columbian-Monkshood%29.png');
