INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Agoseris glauca', 'Pale Dandelion', '1', 'Butterflies, Caterpillars', 'Perennial herb', 'Mounding', '1 - 2 ft', null, 'Fast', null, 'Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Desert, Forest, Wetland/Riparian, Woodland', 'Lodgepole Forest, Northern Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', null, null, 'Adaptable, tolerant of sand, loam and clay', null, null, null, null, 'Slopes, meadows', '3732', '13155', '6.0899999999999999', '115.09', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Agoseris glauca is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 69 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade. Likes slopes and meadows.', null, null, '12', '24', null, null, 'Dandelion, Pale', 'Pale Agoseris,Prairie Agoseris,False Agoseris', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Agoseris+glauca', 'https://calscape.org/Agoseris-glauca-%28Pale-Dandelion%29', 'https://calscape.org/storage/app/media/qr/Agoseris-glauca-%28Pale-Dandelion%29.png');
