INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Agoseris grandiflora', 'California Dandelion', '1', 'Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '2 - 3 ft', null, 'Moderate', null, 'Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, 'Low', null, null, 'Sometimes Available', null, null, 'Chaparral, Forest, Grassland, Woodland', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', null, null, 'Adaptable, tolerant of sand, loam and clay', null, null, null, null, 'Grassy and woodland ares', '2', '8070', '4.6100000000000003', '167.94', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 5.8-7.3. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Agoseris grandiflora is moderately drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes grassy areas.', null, 'For propagating by seed:  No treatment. ( Emery and Frey 1971).', '24', '36', null, null, 'Dandelion, California', 'Large-flowered Agoseris,Grand Mountain Dandelion,Bigflower Agoseris,Grassland Agoseris', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Agoseris+grandiflora', 'https://calscape.org/Agoseris-grandiflora-%28California-Dandelion%29', 'https://calscape.org/storage/app/media/qr/Agoseris-grandiflora-%28California-Dandelion%29.png');
