INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Ambrosia chamissonis', 'Beach Bur', '21', 'Bees, Butterflies, Caterpillars', 'Perennial herb', null, '4 ft', '7 ft', null, 'Evergreen', 'Yellow, Green', 'Summer, Fall', null, 'Full Sun', 'Fast', 'Low', null, null, 'Commonly Available', null, 'Bank stabilization', 'Coastal Scrub', 'Coastal Strand', null, '4, 5, 14, 15, 16, 17*, 19, 20, 21, 22*, 23*, 24*', 'Prefers beach sand', null, null, null, null, 'Beaches, dunes', '0', '1570', '7.6900000000000004', '106.22', 'Requires fast draining soil. Prefers sun. Likes sandy soils.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, null, '48', '48', '84', '84', 'Beachweed, Silver', 'Beach-bur,Silver Burr Ragweed,Silver Beachweed,Silver Bur Ragweed', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Ambrosia+chamissonis', 'https://calscape.org/Ambrosia-chamissonis-%28Beach-Bur%29', 'https://calscape.org/storage/app/media/qr/Ambrosia-chamissonis-%28Beach-Bur%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Ambrosia confertiflora', 'Weakleaf Bur Ragweed', '18', 'Butterflies, Caterpillars', 'Perennial herb', null, null, null, null, null, null, null, null, null, null, null, null, null, 'Never or Almost Never Available', null, null, 'Coastal Scrub, Woodland', 'Coastal Sage Scrub, Southern Oak Woodland', null, null, null, null, null, null, null, null, null, null, '3.98', '36', null, null, null, null, null, null, null, null, 'Weakleaf Burr Ragweed,Ragweed', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Ambrosia+confertiflora', 'https://calscape.org/Ambrosia-confertiflora-%28Weakleaf-Bur-Ragweed%29', 'https://calscape.org/storage/app/media/qr/Ambrosia-confertiflora-%28Weakleaf-Bur-Ragweed%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Ambrosia psilostachya', 'Western Ragweed', '22', 'Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '4 - 7 ft', '1 ft', null, 'Winter Semi-deciduous', 'Green', 'Summer, Fall', null, 'Full Sun', 'Fast, Medium, Slow', 'Low, Moderate, High', 'Max 1x / month once established', null, 'Commonly Available', 'Ambrosia psilostachya can do well in a variety of conditions, so the soil type of your garden will best inform which other plants to choose. Consider using other natives that do well in sunny, sandy sites, such as Nuttall''s scrub oak (Quercus dumosa), Desertbells (Phacelia campanularia), or the Bristly Matilija poppy (Romneya trichocalyx).', 'Groundcover', 'Wetland/Riparian', 'Weed (disturbed places), Wetland-Riparian', 'Tolerates cold to 15&deg; F', null, 'Adaptable', 'Sand, Sandy Clay', '5.2 - 8.2', null, null, 'Commonly occurs throughout California on roadsides, disturbed areas, and dry fields.', '0', '7893', '3.8100000000000001', '115.09', 'Dry or moist soil', null, null, '48', '84', '12', '12', 'Ragweed, Western', 'Ragweed,Cuman Ragweed,Perennial Ragweed', null, 'Common', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Ambrosia+psilostachya', 'https://calscape.org/Ambrosia-psilostachya-%28Western-Ragweed%29', 'https://calscape.org/storage/app/media/qr/Ambrosia-psilostachya-%28Western-Ragweed%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Ambrosia pumila', 'San Diego Ambrosia', '15', 'Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '2 ft', '3 ft', 'Fast, Moderate', 'Summer Semi-deciduous', 'Yellow, Green', 'Summer, Spring, Fall', null, 'Full Sun', 'Fast, Medium', 'Very Low', 'Max 1x / month once established', null, 'Commonly Available', '<p>In the wild it is associated with Saltgrass (Distichlis spicata), Mulefat (Baccharis salicifolia), Broom Baccharis (Baccharis sarathroides), California Buckwheat (Eriogonum fasciculatum), and Turkey-mullein (Croton setiger)</p>', 'Containers', 'Chaparral, Coastal Scrub, Grassland, Wetland/Riparian', 'Chaparral, Coastal Sage Scrub, Freshwater Marsh, Valley Grassland', 'Tolerates cold to 15° F', null, 'Tolerates a variety of soils', null, null, null, null, 'Occurs primarily on upper terraces of rivers and drainages as well as in open grasslands, openings in coastal sage scrub, and occasionally in areas adjacent to vernal pools; may also be found in disturbed sites such as fire fuel breaks and edges of dirt roadways.', '38', '3736', '8.4600000000000009', '22.109999999999999', '<p>Prefers sun.This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as every other week. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'Propagation is by rhizome cutting, rarely from seed', '24', '24', '36', '36', 'Ambrosia, San Diego', 'Dwarf Burr Ragweed,San Diego Ragweed,Dwarf Bur Ragweed', null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Ambrosia+pumila', 'https://calscape.org/Ambrosia-pumila-%28San-Diego-Ambrosia%29', 'https://calscape.org/storage/app/media/qr/Ambrosia-pumila-%28San-Diego-Ambrosia%29.png');
