, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Arnica+longifolia', 'https://calscape.org/Arnica-longifolia-%28Seep-Spring-Arnica%29', 'https://calscape.org/storage/app/media/qr/Arnica-longifolia-%28Seep-Spring-Arnica%29.png');
