INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Asclepias asperula ssp. asperula', 'Antelope-horns', '2', 'Butterflies, Caterpillars', 'Perennial herb', null, null, null, null, null, 'Cream, Red', null, null, null, null, 'Low, Very Low', null, null, 'Never or Almost Never Available', null, null, null, null, null, null, null, null, null, null, null, null, null, null, '4.7300000000000004', '12.9', null, null, null, null, null, null, null, null, null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Asclepias+asperula+subsp.+asperula', 'https://calscape.org/Asclepias-asperula-ssp.-asperula-%28Antelope-horns%29', 'https://calscape.org/storage/app/media/qr/Asclepias-asperula-ssp.-asperula-%28Antelope-horns%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Asclepias californica', 'California Milkweed', '3', 'Birds, Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '3 ft', '3 ft', null, 'Summer Semi-deciduous', 'Lavender, Pink, White', 'Spring, Summer', null, 'Full Sun', 'Fast, Medium, Slow', 'Low, Very Low', 'Max 2x / month once established', null, 'Rarely Available', 'Milkweeds are most often used to create a butterfly garden. A wide variety of trees and shrubs can be used, including Madrone (Arbutus menziesii), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Junipers (<a href="/search/?plant=Juniperus%20(Genus)">Juniperus spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), and Coyote Brush (<a href="/search/?plant=Baccharis%20(Genus)">Baccharis spp.</a>). Also include other butterfly-attracting herbs such as members of the Asteraceae family, other Milkweeds (Asclepias fascicularis or A. speciosa), Thistles (<a href="/search/?plant=Cirsium%20(Genus)">Cirsium spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Mint (<a href="/search/?plant=Monardella%20(Genus)">Monardella spp.</a>), and Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>). To provide year-round attraction, mix early bloomers with late bloomers and evergreens with deciduous.', 'Containers', 'Chaparral, Forest, Woodland', 'Chaparral, Pinyon-Juniper Woodland, Yellow Pine Forest', 'Tolerates cold to 5&deg; F', null, 'Tolerates sand and clay', null, '6.0 - 8.0', null, null, 'Dry slopes, canyons, foothills with chaparral or woodlands; also disturbed areas, roadcuts', '0', '7860', '3.6600000000000001', '54.990000000000002', 'Prefers sun. Likes flats and slopes.', 'It is important to avoid all chemical pest control around milkweeds to protect Monarch butterflies and caterpillars.', 'For propagating by seed:  No treatment.', '36', '36', '36', '36', 'Milkweed, California|Milkweed, Greene''s California', 'Greene''s California Milkweed,Greene''s Milkweed', 'Asclepias californica ssp. greenei', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Asclepias+californica', 'https://calscape.org/Asclepias-californica-%28California-Milkweed%29', 'https://calscape.org/storage/app/media/qr/Asclepias-californica-%28California-Milkweed%29.png');
