INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Baileya multiradiata', 'Wild Marigold', '1', 'Bees, Butterflies, Caterpillars', 'Annual herb, Perennial herb', null, '2 ft', '1 ft', null, 'Summer Semi-deciduous, Winter Semi-deciduous', 'Yellow', 'Spring, Summer', null, 'Full Sun', 'Fast', 'Low, Very Low', 'Max 1x / month once established', 'Moderate', null, 'Works well with other plants of desert or arid areas, including Creosote Bush (Larrea tridentata), Joshua Tree (Yucca brevifolia), Desert Lavender (Condea emoryi), Chuparosa (Justicia californica), Desert Agave (Agave deserti), California Fan Palm (Washingtonia filifera), Smoke Tree (Psorothamnus spinosus), Desert Willow (Chilopsis linearis), Jojoba (Simmondsia chinensis), and various cactus species', 'Containers, Deer resistant', 'Desert', 'Creosote Bush Scrub, Joshua Tree Woodland', 'Tolerates cold to 5&deg; F', '7, 8, 9, 10*, 11*, 12*, 13*, 14, 18*, 19*, 20*, 21*, 22, 23', 'Typically sandy and/or rocky', null, '7.0 - 9.0', null, 'Inorganic', 'Desert, flats, washes, slopes and inland valleys', '-15', '6483', '0', '27.239999999999998', 'Requires fast draining soil. Prefers sun. Likes sandy soils.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as every other week.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'For propagating by seed:  No treatment.', '24', '24', '12', '12', 'Marigold, Wild|Marigold, Desert', 'Desert Marigold,Desert Baileya', 'Baileya multiradiata var. multiradiata', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Baileya+multiradiata', 'https://calscape.org/Baileya-multiradiata-%28Wild-Marigold%29', 'https://calscape.org/storage/app/media/qr/Baileya-multiradiata-%28Wild-Marigold%29.png');
