INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Balsamorhiza hookeri', 'Hooker''s Balsamroot', '0', null, 'Perennial herb', 'Upright', '1 ft', null, 'Moderate', 'Winter Deciduous', 'Yellow', 'Spring', null, 'Full Sun', null, null, null, null, null, null, null, 'Desert, Forest, Woodland', 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', null, null, 'Adaptable, tolerant of sand, loam and clay', null, null, null, null, 'Open woods, grassy slopes', '2296', '7244', '6.2000000000000002', '91', 'Plant in sandy, loamy or clay soils that are at least 18 inches deep, with a pH of 6.6-9. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Balsamorhiza hookeri is moderately drought tolerant. It requires a minimum of 9 inches of water per year, and a maximum of 20 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes slopes.', null, null, '12', '12', null, null, 'Balsamroot, Hooker''s|Balsamroot, Flat Scale|Flat Scale Balsam Root', 'Hairy Balsamroot,Hooker Balsamroot', 'Balsamorhiza macrolepis var. platylepis', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Balsamorhiza+hookeri', 'https://calscape.org/Balsamorhiza-hookeri-%28Hooker%27s-Balsamroot%29', 'https://calscape.org/storage/app/media/qr/Balsamorhiza-hookeri-%28Hooker%27s-Balsamroot%29.png');
