INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Balsamorhiza sagittata', 'Arrow Leaved Balsam Root', '1', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '8 - 24 in', null, 'Moderate', null, 'Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, 'Moderate', 'Rarely Available', null, null, 'Desert, Forest, Woodland', 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, 'Open places', '2445', '9149', '4.79', '116.06', 'Plant in loamy or clay soils that are at least 14 inches deep, with a pH of 6.5-8. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Balsamorhiza sagittata is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 25 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'For propagating by seed:  3 mos. stratification ( Young and Evans 1979). Check periodically to remove and pot germinating seeds.', '8', '24', null, null, 'Balsam Root, Arrow Leaved', 'Arrow-leaf Balsamroot,Arrow Leaved Balsamroot,Arrowleaf Balsamroot', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Balsamorhiza+sagittata', 'https://calscape.org/Balsamorhiza-sagittata-%28Arrow-Leaved-Balsam-Root%29', 'https://calscape.org/storage/app/media/qr/Balsamorhiza-sagittata-%28Arrow-Leaved-Balsam-Root%29.png');
