INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Bidens laevis', 'Bur Marigold', '8', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '8 - 96 in', null, 'Fast', null, 'Yellow', 'Summer, Fall', null, 'Full Sun', null, 'High, Moderate', null, null, 'Sometimes Available', null, null, 'Wetland/Riparian', 'Freshwater Marsh, Wetland-Riparian', null, '7, 8*, 9*, 10, 11, 12*, 14*, 15*, 16*, 18*, 19*, 20*, 21*, 22*, 23*, 24*', 'Adaptable, tolerant of sand, loam and clay', null, null, null, null, null, '-7', '5295', '4.0599999999999996', '74.659999999999997', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 5-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Bidens laevis is only slightly drought tolerant. It requires a minimum of 24 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.This plant is tough and fairly easy to grow.  It''s very drought tolerant. After established, it should survive the dry months with no supplementary water. It''s also very garden tolerant, and can handle weekly watering without much trouble.', null, 'For propagating by seed:  No treatment.', '8', '96', null, null, 'Marigold, Bur', 'Smooth Beggartick,Bur-marigold,Smooth Beggarticks', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Bidens+laevis', 'https://calscape.org/Bidens-laevis-%28Bur-Marigold%29', 'https://calscape.org/storage/app/media/qr/Bidens-laevis-%28Bur-Marigold%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Bistorta bistortoides', 'Western Bistort', '26', 'Butterflies, Caterpillars', 'Perennial herb', null, '4 - 12 in', null, null, null, 'Pink, White', null, null, 'Full Sun', null, null, null, null, 'Never or Almost Never Available', null, 'Water features or wet habitats', 'Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', null, '1*, 2*, 3*, 4*, 5*, 6*, 7, 15, 16, 17, 18', null, null, null, null, null, 'Wet meadows', '0', '11361', '4.79', '167.94', 'Plant in sandy or loamy soils that are at least 16 inches deep, with a pH of 6.5-8. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Polygonum bistortoides is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 30 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes wet meadows.', null, null, '4', '12', null, null, 'American Bistort|Snakeweed|Bistort, Western', 'American Bistort,Snakeweed,Western Knotweed', 'Polygonum bistortoides