INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Camissoniopsis cheiranthifolia', 'Beach Primrose', '4', 'Butterflies, Caterpillars', 'Perennial herb', 'Mounding, Spreading', '1 - 4 in', '6 - 36 in', 'Fast', 'Evergreen', 'Red, Yellow', 'Summer, Spring, Winter', null, 'Full Sun', 'Fast', 'Very Low, Low', 'Max 1x / month once established', 'Moderate', 'Commonly Available', '<p>Coast Eriogonum (Eriogonum latifolium),Sand Verbena (<a href="/search/?plant=Abronia%20(Genus)">Abronia spp.</a>), Pt. Reyes Ceanothus (Ceanothus gloriosus), Twinberry (Lonicera involucrata), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Bluff Lettuce (Dudleya farinosa), Coast Silktassel (Garrya elliptica), Yellow Stonecrop (Sedum spathulifolium), and Dune Manzanita (Arctostaphylos pumila), Coastal plants such as other Verbena species (Abronia maritima, Abronia umbellata), Common Yarrow (Achillea millefolium), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Saltbush species (<a href="/search/?plant=Atriplex%20(Genus)">Atriplex spp.</a>), Cakile maritima, Morning-glory species (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Sandcarpet (Cardionema ramosissimum), Croton (Croton californicus), Seaside Daisy species (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Buckwheat species (Eriogonum latifolium, Eriogonum parvifolium), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Wallflower (<a href="/search/?plant=Erysimum%20(Genus)">Erysimum spp.</a>), Beach Strawberry (Fragaria chiloensis), Coastal Gumplant (Grindelia stricta)</p>', 'Lawn alternative', 'Coastal Scrub', 'Coastal Strand', 'Tolerates cold to 25 - 30° F', null, 'Sandy dunes', 'Sand, Sandy Clay, Sandy Clay Loam, Sandy Loam', '5 - 7', null, null, 'Coastal sandy slopes and flats, dunes', '0', '1845', '8.9299999999999997', '77.670000000000002', '<p>Prefers sun. Likes sandy slopes. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'Reseeds readily', '1', '4', '6', '36', 'Beach Evening Primrose|', 'Beach Evening-primrose,Beach Suncup,Beach Evening Primrose', 'Camissonia cheiranthifolia', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Camissoniopsis+cheiranthifolia', 'https://calscape.org/Camissoniopsis-cheiranthifolia-%28Beach-Primrose%29', 'https://calscape.org/storage/app/media/qr/Camissoniopsis-cheiranthifolia-%28Beach-Primrose%29.png');
