INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Castilleja exserta', 'Purple Owl''s Clover', '18', 'Bats, Bees, Butterflies, Caterpillars', 'Annual herb', null, '2 ft', '1 ft', 'Fast, Moderate', null, 'Lavender, Pink, Purple, White', 'Spring', null, 'Full Sun', 'Fast, Medium, Slow', 'Very Low, Low', null, 'Moderate', 'Commonly Available', 'Use in a meadow-like planting with other annuals such as <a href="/search/?plant=Clarkis%20(Genus)">Clarkis spp.</a>, California Poppy (Eschscholzia californica), Baby Blue-eyes (Nemophila menziesii), and Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>); also with geophytes such as wild onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Ithuriels''s Spear (Triteleia laxa), Blue Dicks (Dichelostemma capitatum), and Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>).', null, 'Chaparral, Coastal Scrub, Desert, Grassland, Woodland', 'Chaparral, Coastal Sage Scrub, Coastal Strand, Creosote Bush Scrub, Foothill Woodland, Joshua Tree Woodland, Northern Coastal Scrub, Valley Grassland', 'Tolerates cold to 15&deg; F', null, 'Tolerant of sand and clay, prefers fast-draining soil', null, '5.0 - 8.0', null, null, 'Grasslands and openings in chaparral or woodlands; occasionally in desert areas', '0', '6442', '0', '88.430000000000007', 'Prefers sun. Likes grassy areas.', null, 'By seed. It must be planted with a perennial host plant such as a native grass (Stipa, Fescue, or other species). Some propagation protocols also recommend Beardtongue (Penstemon spp.), Common Spikeweed (Hemizonia pungens), Low Barley (Hordeum depressum), or Alkali-Sink Goldfields (Lasthenia chrysantha).', '24', '24', '12', '12', 'Clover, Purple Owl''s', 'Owl''s Clover,Exserted Indian Paintbrush', 'Orthocarpus purpurascens', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Castilleja+exserta', 'https://calscape.org/Castilleja-exserta-%28Purple-Owl%27s-Clover%29', 'https://calscape.org/storage/app/media/qr/Castilleja-exserta-%28Purple-Owl%27s-Clover%29.png');
