INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Castilleja hispida', 'Harsh Indian Paintbrush', '8', 'Butterflies, Caterpillars', 'Annual herb, Perennial herb', 'Upright', '10 - 19 in', null, 'Fast', 'Winter Deciduous', 'Red, Red', 'Spring', null, 'Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Forest', 'Yellow Pine Forest', null, null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, 'Dry open places', '327', '7753', '36.670000000000002', '160.97', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Castilleja hispida is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 19 inches of water per year once established. It does not tolerate full shade well. Prefers part shade.', null, null, '10', '19', null, null, 'Indian Paintbrush , Harsh', null, null, 'Uncommon', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Castilleja+hispida', 'https://calscape.org/Castilleja-hispida-%28Harsh-Indian-Paintbrush%29', 'https://calscape.org/storage/app/media/qr/Castilleja-hispida-%28Harsh-Indian-Paintbrush%29.png');
