INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Cicuta douglasii', 'Western Water Hemlock', '5', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 10 ft', null, 'Fast', null, 'White', 'Spring', null, 'Partial Shade', null, 'Moderate, High', null, null, 'Rarely Available', null, null, 'Chaparral, Forest, Grassland, Wetland/Riparian, Woodland', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, 'Wet places, often in water', '38', '12825', '4.6399999999999997', '133.88999999999999', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 4.8-7. It is tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Cicuta douglasii is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 30 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers part shade. Likes wet soils.', null, null, '24', '120', null, null, 'Hemlock, Western Water', 'Western Water-hemlock', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Cicuta+douglasii', 'https://calscape.org/Cicuta-douglasii-%28Western-Water-Hemlock%29', 'https://calscape.org/storage/app/media/qr/Cicuta-douglasii-%28Western-Water-Hemlock%29.png');
