INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Dichondra occidentalis', 'Western Ponysfoot', '0', null, 'Perennial herb', null, null, null, null, null, 'Cream', 'Spring, Summer', null, 'Full Sun, Partial Shade', null, 'Low, Moderate, Very Low', null, 'Moderate', 'Rarely Available', null, null, 'Chaparral, Coastal Scrub, Grassland, Woodland', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Northern Coastal Scrub, Valley Grassland', null, '17*, 18, 19, 22, 23, 24*', null, null, null, null, null, 'Slopes, headlands, under shrubs', '6', '2495', '9.4000000000000004', '45.189999999999998', 'Requires fast draining soil. Prefers sun, part shade. Likes slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as every other week.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, null, null, null, null, null, 'Ponysfoot, Western', 'Western Dichondra', null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Dichondra+occidentalis', 'https://calscape.org/Dichondra-occidentalis-%28Western-Ponysfoot%29', 'https://calscape.org/storage/app/media/qr/Dichondra-occidentalis-%28Western-Ponysfoot%29.png');
