INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Dipterostemon capitatus', 'Blue Dicks', '0', 'Butterflies', 'Perennial herb, Geophyte', 'Upright Columnar', '2 ft', '2 in', 'Moderate', 'Summer Deciduous', 'Blue, Lavender', 'Spring, Winter', 'Slight', 'Full Sun, Partial Shade', 'Fast, Medium, Slow', 'Low', 'Never irrigate once established', 'Moderate', 'Commonly Available', '<p>Native grasses, <a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>, Coast Sagebush, Chamise (Adenostoma fasciculatum var. fasciculatum), Sugar Bush (Rhus ovata), <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, various cactus species</p>', 'Deer resistant, Groundcover', 'Chaparral, Coastal Scrub, Desert, Grassland, Meadow', 'Chaparral, Coastal Scrub, Creosote Bush Scrub, Lowland Chaparral, Maritime Desert Scrub, Meadows, Perennial Grassland--Desert Grassland, Perennial Grassland--Remnant Non-desert Grassland, Southern Coastal Scrub', 'Tolerates cold to -20° F', null, 'Adaptable', 'Sand, Sandy Clay, Sandy Clay Loam, Sandy Loam', null, null, null, 'Open places,meadows, grassy places, openings in mixed chaparral or coastal sage scrub on rocky slopes, canyons and mesas. Also found in desert transition zone.', '0', '7186', '0', '167.94', '<p>Requires moist soil. Prefers sun or part shade.This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'The offsets from the corms can be removed and replanted elsewhere. The seeds also germinate relatively well in open soil that has no weeds and minimal mulch. Corms are often available from specialty bulb vendors or CNPS plant sales.', '24', '24', '2', '2', 'Dicks, Blue', 'Blue Dips,Wild Hyacinth,Vernal Pool Blue Dicks', 'Brodiaea pulchella|Dichelostemma capitatum', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Dipterostemon+capitatus', 'https://calscape.org/Dipterostemon-capitatus-%28Blue-Dicks%29', 'https://calscape.org/storage/app/media/qr/Dipterostemon-capitatus-%28Blue-Dicks%29.png');
