INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Dudleya densiflora', 'San Gabriel Mountains Dudleya', '3', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Perennial herb, Succulent', null, '4 - 8 in', null, null, null, 'White, Pink', null, null, null, null, 'Low, Very Low', null, null, 'Never or Almost Never Available', null, 'Containers, Lawn alternative', null, null, null, null, null, null, null, null, null, null, null, null, '7.8399999999999999', '50.280000000000001', null, null, null, '4', '8', '0', '0', null, 'San Gabriel Mountains Liveforever,San Gabriel Mtns. Dudleya', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Dudleya+densiflora', 'https://calscape.org/Dudleya-densiflora-%28San-Gabriel-Mountains-Dudleya%29', 'https://calscape.org/storage/app/media/qr/Dudleya-densiflora-%28San-Gabriel-Mountains-Dudleya%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Dudleya edulis', 'Fingertips', '3', 'Birds, Butterflies, Caterpillars, Hummingbirds', 'Perennial herb, Succulent', 'Fountain', '4 - 8 in', '1 ft', 'Moderate', 'Evergreen', 'Pink, Cream, White', 'Summer, Spring', 'None', 'Full Sun, Partial Shade', 'Fast, Medium', 'Very Low, Low', 'Max 1x / month once established', 'Easy', 'Commonly Available', '<p>California Fuchsia (Epilobium canum ssp. latifolium), California Box Thorn (Lycium californicum), Sea Dahlia (Leptosyne maritima), Seacliff Buckwheat, various cactus species</p>', 'Containers, Groundcover', 'Chaparral, Coastal Scrub, Desert', 'Chaparral, Coastal Scrub, Lowland Chaparral, Maritime Desert Scrub, Southern Coastal Scrub', 'Tolerates cold to 10° F', '14, 15*, 16*, 17*, 19, 20*, 21*, 22*, 23*, 24*', 'While it appears to be tolerant of a variety garden soils, it is found in the wild almost entirely in sandstone soils', 'Sand', '6.0 - 8.0', null, 'Inorganic', 'Sandstone bluffs, marine terraces, rocky slopes, ledges, canyons and mesas on the coastal side of the mountains of San Diego, Orange and Riverside Counties; especially common in close proximity to the coast', '6', '6591', '6.6200000000000001', '31.43', '<p>Requires fast draining soil and prefers sun. Likes rocky slopes that get some natural ground water, and typically are not south facing. This plant looks best if given summer water every 4 weeks after even after it''s established. Without additional water, this plant typically goes summer deciduous, dries up and virtually disappears in the summer, but then come back strong and green once the winter rains start.</p>', null, 'Propagation by seed is difficult as the seeds are very fine and dust-like. For propagating by seed:  No treatment.', '4', '8', '12', '12', null, 'Lady Fingers,Dead Man''s Fingers', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Dudleya+edulis', 'https://calscape.org/Dudleya-edulis-%28Fingertips%29', 'https://calscape.org/storage/app/media/qr/Dudleya-edulis-%28Fingertips%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Dudleya farinosa', 'Bluff Lettuce', '3', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Perennial herb, Succulent', 'Mounding', '4 - 8 in', '8 - 12 in', 'Moderate', 'Summer Semi-deciduous', 'Red, Yellow, Pink, Green', 'Summer', null, 'Deep Shade, Partial Shade', 'Fast', 'Low, Very Low', 'Max 1x / month once established', null, 'Commonly Available', 'Yellow Stonecrop (Sedum spathulifolium), Coast Dudleya (Dudleya caespitosa), Red Maids (Calandrinia menziesii), dwarf or low growing Chamise (Adenostoma fasciculatum), Giant Coreopsis (Leptosyne gigantea), low growing Coyote Bush (Baccharis pilularis), Coast Eriogonum (Eriogonum latifolium), Seaside Fleabane (Erigeron glaucus), Coastal Sagewort (Artemisia pycnocephala)', 'Containers', 'Coastal Scrub', 'Coastal Sage Scrub, Northern Coastal Scrub', 'Tolerates cold to 25 - 30&deg; F', '5, 7, 14*, 15*, 16*, 17*, 19*, 20*, 21*, 22*, 23*, 24*', 'Rocky cliffs, very well draining rocky slopes', null, '6 - 7', null, 'Inorganic', 'Sea cliffs and bluffs', '0', '1204', '13.710000000000001', '167.94', 'Requires fast draining soil. Prefers shade.', null, 'For propagating by seed:  No treatment.', '4', '8', '8', '12', 'Lettuce, Bluff', 'Sea Lettuce,North Coast Dudleya,Powdery Liveforever,Powdery Dudleya', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Dudleya+farinosa', 'https://calscape.org/Dudleya-farinosa-%28Bluff-Lettuce%29', 'https://calscape.org/storage/app/media/qr/Dudleya-farinosa-%28Bluff-Lettuce%29.png');
