INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Epilobium canum', 'California Fuchsia', '15', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Spreading', '3 - 18 in', '2 - 3 ft', 'Fast', 'Winter Semi-deciduous', 'Red', 'Summer, Fall', 'None', 'Full Sun, Partial Shade', 'Fast, Medium, Slow', 'Very Low, Low', 'Max 1x / month once established', 'Easy', 'Commonly Available', 'Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Giant Wild Rye (Elymus condensatus), Sand Aster (Corethrogyne filaginifolia), Sagebrush (Artemisia californica), Monkeyflower (<a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>), Encelia californica, Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Heartleaf Keckiella (Keckiella cordifolia), Penstemon species, Salvia species, Blue-eyed Grass (Sisyrinchium bellum)', 'Containers, Deer resistant, Groundcover', 'Chaparral, Coastal Scrub, Forest, Woodland', 'Chaparral, Coastal Sage Scrub, Lodgepole Forest, Oak Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Tolerates cold to 0&deg; F', null, 'Tolerates clay and sand', null, '6.0 - 8.0', 'Tolerates serpentine soil.', null, 'This species is found in a number of natural settings over a large part of the state. Near the coast, it is found on slopes, bluffs or canyons as part of chaparral or coastal scrub. In more inland areas including the Sierra, it is found in slightly damper slopes and flats, often near seasonal creeks, often as part of pine or fir forest.', '2', '11399', '0', '160.97', 'Prefers sun. Likes dry slopes. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'Self-seeds readily. Rhizomes can be transplanted in winter or spring.', '3', '18', '24', '36', 'Fuchsia, California', 'Hummingbird Trumpet', 'Zauschneria californica|Zauschneria canum', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Epilobium+canum', 'https://calscape.org/Epilobium-canum-%28California-Fuchsia%29', 'https://calscape.org/storage/app/media/qr/Epilobium-canum-%28California-Fuchsia%29.png');
