INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Eriogonum fasciculatum', 'California Buckwheat', '52', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Shrub, Perennial herb', 'Rounded, Mounding, Spreading', '1 - 7 ft', '3 ft', 'Fast, Slow', 'Evergreen', 'Yellow, Cream, Pink, White', 'Summer, Spring, Fall', null, 'Full Sun', 'Fast, Medium, Slow', 'Low, Very Low', 'Max 1x / month once established, Never irrigate once established', 'Easy', 'Commonly Available', '<p>Many companions including Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Sagebrush (<a href="/search/?plant=Artemisia%20(Genus)">Artemisia spp.</a>), Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Ceanothus species, Yucca species, Dudleya species, and cactus species</p>', 'Bank stabilization, Deer resistant, Groundcover', 'Chaparral, Coastal Scrub, Desert, Woodland', 'Chaparral, Coastal Scrub, Creosote Bush Scrub, Desert-Holly Scrub, Joshua Tree Woodland, Pine-Juniper Woodland, Sagebrush, Shadscale Scrub, Southern Oak Woodland', 'Tolerates cold to 15° F', null, 'Prefers loamy soils', null, '5.0 - 8.5', null, null, 'Dry slopes, often south facing as a common component of Coastal Sage Scrub. Inland it may be found in Valley Grassland. In high desert areas, it occurs in Sagebrush Scrub and Pinyon-Juniper Woodland. It sometimes occurs in low desert areas as part of Creosote Bush Scrub', '6', '12885', '0', '84.599999999999994', '<p>Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 7.5-8.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. It requires a minimum of 8 inches of water per year, and a maximum of 20 inches of water per year once established. Requires fast draining soil. It does not tolerate shade well and prefers sun. Likes dry south facing slopes. It should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'For propagating by seed:  No treatment.', '12', '84', '36', '36', 'Buckwheat, California', 'Eastern Mojave Buckwheat,Flattop Buckwheat,Yellow Buckwheat', null, 'Common', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Eriogonum+fasciculatum', 'https://calscape.org/Eriogonum-fasciculatum-%28California-Buckwheat%29', 'https://calscape.org/storage/app/media/qr/Eriogonum-fasciculatum-%28California-Buckwheat%29.png');
