INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Eriogonum sphaerocephalum', 'Round Headed Buckwheat', '25', 'Bees, Butterflies, Caterpillars', 'Perennial herb', 'Mounding', '1 - 2 ft', null, 'Slow', null, 'Yellow, Cream, Pink, White', 'Spring', null, 'Partial Shade', null, 'Low, Very Low', null, null, 'Never or Almost Never Available', null, null, 'Desert, Forest, Woodland', 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', null, null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, null, '2232', '8056', '6.2000000000000002', '117.20999999999999', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6-8.6. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Eriogonum sphaerocephalum is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate full shade well. Prefers part shade.', null, null, '12', '24', null, null, 'Buckwheat, Round Headed', 'Rock Buckwheat', null, 'Common', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Eriogonum+sphaerocephalum', 'https://calscape.org/Eriogonum-sphaerocephalum-%28Round-Headed-Buckwheat%29', 'https://calscape.org/storage/app/media/qr/Eriogonum-sphaerocephalum-%28Round-Headed-Buckwheat%29.png');
