INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Erythranthe lewisii', 'Lewis'' Monkeyflower', '9', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', null, '10 - 31 in', null, null, 'Winter Deciduous', 'Pink, Purple, Red', 'Summer', null, 'Full Sun', 'Medium', 'High', 'Max 1x / week once established', 'Easy', 'Commonly Available', '<p>Trees: White Fir (Abies concolor), Rocky Mountain Maple, (Acer glabrum), Western Juniper (Juniperus occidentalis), Pine (Pinus contorta or monticola), Cottonwood (<a href="/search/?plant=Populus%20(Genus)">Populus spp.</a>), Canyon Oak (Quercus chrysolepis)</p><p><br></p><p><br></p><p>Shrubs: Pine Mat Manzanita (Arctostaphylos nevadensis), Dogwood (Cornus nuttallii or sericea), Honeysuckle (<a href="/search/?plant=Lonicera%20(Genus)">Lonicera spp.</a>), Currant/Gooseberry (Ribes spl.), and Huckleberry (<a href="/search/?plant=Vaccinium%20(Genus)">Vaccinium spp.</a>)</p><p><br></p><p><br></p><p>Herbs: Sitka Columbine (Aquilegia formosa), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Sulphur Buckwheat (Eriogonum umbellatum), Gentian (<a href="/search/?plant=Gentianella%20(Genus)">Gentianella spp.</a> or <a href="/search/?plant=Gentianopsis%20(Genus)">Gentianopsis spp.</a>), Pink Alumroot (Heuchera rubescens), Alpine Lily (Lilium parvum), other <a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>, Idaho Blue Eyed Grass (Sisyrinchium idahoense), and <a href="/search/?plant=Viola%20(Genus)">Viola spp.</a></p>', 'Containers, Deer resistant', 'Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to -10 &deg;F', '1*, 2, 3, 4, 5, 6, 7, 14, 15, 16, 17, 18, 19, 20, 21', 'Prefers rich, moist, loamy soil', null, '5.0 - 7.0', null, null, 'Streambanks, seeps at mid-to-high elevations in the Sierras', '3555', '11483', '4.79', '115.66', '<p>Requires fast draining soil. Prefers sun. Likes streambanks and seeps.</p>', null, 'For propagating by seed:  No treatment.', '10', '31', '0', '0', 'Monkeyflower, Great Purple', 'Lewis'' Monkey-flower,Great Purple Monkeyflower,Purple Monkeyflower', 'Mimulus lewisii|Diplacus lewisii', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Erythranthe+lewisii', 'https://calscape.org/Erythranthe-lewisii-%28Lewis%27-Monkeyflower%29', 'https://calscape.org/storage/app/media/qr/Erythranthe-lewisii-%28Lewis%27-Monkeyflower%29.png');
