eatment.', '1', '5', null, null, 'Monkeyflower, Primrose', 'Primrose Monkey-flower,Yellow Creeping Monkey-flower', 'Mimulus primuloides var. primuloides|Mimulus primuloides|Diplacus primuloides', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Erythranthe+primuloides', 'https://calscape.org/Erythranthe-primuloides-%28Primrose-Monkeyflower%29', 'https://calscape.org/storage/app/media/qr/Erythranthe-primuloides-%28Primrose-Monkeyflower%29.png');
