INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Heuchera maxima', 'Island Alum Root', '0', 'Birds, Hummingbirds', 'Perennial herb', null, '1 - 2 ft', '2 ft', 'Moderate', 'Evergreen', 'Pink, White', 'Spring, Winter', 'None', 'Full Sun, Partial Shade, Deep Shade', 'Fast, Medium', 'Low, Moderate', 'Max 3x / month once established', 'Easy', 'Commonly Available', '<p>Use with other Channel Island species such as:</p><p><br></p><p>Trees: Island Ironwood (Lyonothamnus floribundus ssp. asplenifolius), Island Cherry (Prunus ilicifolia ssp. lyonii), Island Oak (Quercus tomentella)</p><p><br></p><p>Shrubs and herbs: Island Ceanothus (Ceanothus arboreus), California Encelia (Encelia californica), St. Catherine''s Lace (Eriogonum giganteum), Santa Rosa Island Sage (Salvia brandegeei), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, Yucca species</p>', 'Containers, Groundcover, Lawn alternative', 'Chaparral, Coastal Scrub', 'Chaparral, Coastal Sage Scrub', 'Tolerates cold to 12° F', null, 'Prefers sandy/rocky soil with good drainage', null, '6.0 - 8.0', null, 'Deep Organic', 'Chaparral or coastal sage scrub on rocky or sandy cliffs and sea bluffs of the northern Channel Islands', '218', '1076', '11.84', '19.16', '<p>Prefers part shade in coastal regions (without salt spray). Likes rock walls. Tolerates clay rich and alkaline soils. It likes summer water every 2-4 weeks. Great to use as a groundcover under evergreen oaks; does well with mulch if there isn''t enough leaf litter.</p>', null, 'For propagating by seed:  No treatment.', '12', '24', '24', '24', 'Alumroot, Islan', 'Jill Of The Rocks,Island Alumroot,Jill-of-the-rocks', null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Heuchera+maxima', 'https://calscape.org/Heuchera-maxima-%28Island-Alum-Root%29', 'https://calscape.org/storage/app/media/qr/Heuchera-maxima-%28Island-Alum-Root%29.png');
