INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Heuchera micrantha', 'Crevice Alumroot', '1', 'Butterflies, Caterpillars, Hummingbirds', 'Perennial herb', null, '1 - 3 ft', '1 ft', null, 'Evergreen', 'Green, Purple, Pink, White', 'Summer, Spring', null, 'Partial Shade, Deep Shade', 'Medium', 'Moderate', 'Max 1x / month once established', null, 'Commonly Available', '<p>Trees: Tanoak (Notholithocarpus densiflorus), Madrone (Arbutus menziesii), Douglas Fir (Pseudotsuga menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Bay Laurel (Umbellularia californica), Red Fir (Abies magnifica), Ponderosa Pine (Pinus ponderosa)</p><p>Other plants: Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Coffeeberry (Frangula californica), Coast Silktassel (Garrya elliptica), Oceanspray (Holodiscus discolor), <a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>, Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Sticky Monkeyflower (Diplacus aurantiacus), Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), Snowberry (Symphoricarpos albus or mollis)</p>', 'Containers, Deer resistant, Groundcover', 'Forest', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Red Fir Forest, Forest, Yellow Pine Forest', 'Tolerates cold to 16 °F', null, 'Prefers rocky substrate', null, '5 - 8', null, null, 'Moist, rocky banks and cliffs', '0', '11640', '9.8100000000000005', '167.94', '<p>Requires fast draining soil. Prefers shade. Likes moist rocky slopes.</p>', null, 'For propagating by seed:  No treatment.', '12', '36', '12', '12', 'Alumroot, Crevice', null, 'Heuchera micrantha var. diversifolia|Heuchera micrantha var. micrantha|Heuchera micrantha var. erubescens', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Heuchera+micrantha', 'https://calscape.org/Heuchera-micrantha-%28Crevice-Alumroot%29-4', 'https://calscape.org/storage/app/media/qr/Heuchera-micrantha-%28Crevice-Alumroot%29-4.png');
