INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Hydrophyllum capitatum', 'Ballhead Waterleaf', '0', null, 'Perennial herb', 'Upright', '1 ft', null, 'Fast', 'Winter Deciduous', 'Purple', 'Spring', null, 'Full Sun, Partial Shade, Deep Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Desert, Forest', 'Sagebrush Scrub, Yellow Pine Forest', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, 'Moist places', '3122', '10401', '10.02', '115.09', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 6.4-7.8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Hydrophyllum capitatum is only slightly drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers sun or shade.', null, null, '12', '12', null, null, 'Waterleaf, Ballhead', null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Hydrophyllum+capitatum', 'https://calscape.org/Hydrophyllum-capitatum-%28Ballhead-Waterleaf%29', 'https://calscape.org/storage/app/media/qr/Hydrophyllum-capitatum-%28Ballhead-Waterleaf%29.png');
