INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lilium bolanderi', 'Bolander''s Lily', '1', 'Butterflies, Caterpillars', 'Perennial herb, Geophyte', null, '3 ft', null, null, null, 'Yellow, Purple, Red', null, null, 'Full Sun, Partial Shade, Deep Shade', null, 'Moderate', null, null, 'Never or Almost Never Available', null, null, 'Chaparral, Forest, Wetland/Riparian', 'Chaparral, Yellow Pine Forest, Wetland-Riparian', null, '4, 5, 6, 7*, 14, 15, 16, 17', null, null, null, null, null, null, '567', '5444', '32.969999999999999', '160.97', 'Requires fast draining soil. Prefers shade or part shade.', null, 'For propagating by seed:  Sow outdoors in summer for germination the following spring, or 3-6 mos. warm then 2-3 mos. cold stratification. For forcing slightly green or fresh seeds: 6-8 wks. warm (70&deg;F) stratification or until the majority of seeds have formed bulblets; then 4-6 wks. cold (about 35&deg;F) stratification; sow, and at 55 to 60&deg;F leaves should be produced in 4-6 wks. (De Graaff 1951).', '36', '36', null, null, 'Lily, Bolander''s', null, null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Lilium+bolanderi', 'https://calscape.org/Lilium-bolanderi-%28Bolander%27s-Lily%29', 'https://calscape.org/storage/app/media/qr/Lilium-bolanderi-%28Bolander%27s-Lily%29.png');
