INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lilium pardalinum', 'Tiger Lily', '3', 'Butterflies, Hummingbirds, Caterpillars', 'Perennial herb, Geophyte', 'Weeping', '7 - 8 ft', '6 in', null, 'Winter Deciduous', 'Orange, Red, Brown', 'Summer', null, 'Partial Shade, Full Sun', 'Slow', 'Low, Moderate, Very Low', 'Max 1x / week once established', null, 'Commonly Available', 'Trees: Coast Redwood (Sequoia sempervirens), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Madrone (Arbutus menziesii), Incense Cedar (Calocedrus decurrens), Coast Silktassel (Garrya elliptica), Tanoak (Notholithocarpus densiflorus), Douglas Fir (Pseudotsuga menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), California Laurel (Umbellularia californica), and others<br><br>Shrubs/herbs: Oneleaf Onion (Allium unifolium), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Barberry (<a href="/search/?plant=Berberis%20(Genus)">Berberis spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Miner''s Lettuce (Claytonia perfiolata), Yerba Buena (Clinopodium douglasii), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Crevise Alumroot (Heuchera micrantha), <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, Pink Honeysuckle (Lonicera hispidula), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Currant (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), <a href="/search/?plant=Trillium%20(Genus)">Trillium spp.</a>, <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a>, and <a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>', null, 'Forest, Wetland/Riparian', 'Mixed Evergreen Forest, North Coastal Coniferous Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to -15&deg; F', null, 'Tolerates a variety of soils including clay and serpentine and acidic soils', null, '4.0 - 8.0', 'Tolerates serpentine soil.', null, 'Moist places such as along stream banks, lake shoreline, or near seeps or springs', '2', '11877', '6.2000000000000002', '167.94', 'Requires moist soil. Prefers part shade.', null, 'For propagating by seed:  Sow outdoors in summer for germination the following spring, or 3-6 mos. warm then 2-3 mos. cold stratification. For forcing slightly green or fresh seeds: 6-8 wks. warm (70&deg;F) stratification or until the majority of seeds have formed bulblets; then 4-6 wks. cold (about 35&deg;FJ stratification; sow, and at 55 to 60&deg;F leaves should be produced in 4-6 wks. (De Graaff 1951).', '84', '96', '6', '6', 'Lily, Tiger', 'California Tiger Lily,Leopard Lily', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Lilium+pardalinum', 'https://calscape.org/Lilium-pardalinum-%28Tiger-Lily%29', 'https://calscape.org/storage/app/media/qr/Lilium-pardalinum-%28Tiger-Lily%29.png');
