INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Linnaea borealis', 'WesternTwinflower', '0', null, 'Perennial herb', 'Spreading', '2 - 8 in', '3 ft', 'Very Slow', 'Evergreen', 'Pink', null, 'Pleasant', 'Deep Shade, Partial Shade', null, null, 'Max 1x / month once established', null, 'Never or Almost Never Available', 'Plant with other associated forest species, such as Cascara Sagrada (Frangula purshiana), Western Azalea (Rhododendron occidentale), Western Brakenfern (Pteridium aquilinum), and Bigflower Tellima (Tellima grandiflora).', 'Groundcover', 'Forest, Wetland/Riparian', 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to 5&deg; F', null, 'Moist, acidic soil', 'Sand, Sandy Loam', '5 - 6', null, null, 'Moist places', '27', '13322', '15.81', '160.97', 'Requires fast draining soil. Prefers shade. Likes moist soils.', null, 'Most effective way to propagate this plant is through stem cuttings (late spring) or by layering as seeds can be difficult to collect and seed germination rate is quite low. With cuttings, divide young, rooted runners and carefully detach from parent plant.', '2', '8', '36', '36', null, null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Linnaea+borealis', 'https://calscape.org/Linnaea-borealis-%28WesternTwinflower%29', 'https://calscape.org/storage/app/media/qr/Linnaea-borealis-%28WesternTwinflower%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Linnaea borealis var. longiflora', 'Twin Flower', '0', null, 'Perennial herb', 'Spreading', '2 - 3 in', '3 ft', null, 'Evergreen', 'Pink', null, 'Pleasant', 'Deep Shade, Partial Shade', null, null, null, null, 'Never or Almost Never Available', 'Western Azalea (Rhododendron occidentale)', 'Groundcover', 'Forest, Wetland/Riparian', 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to 5&deg; F', '1, 2, 4, 5, 6, 14, 15, 16, 17', 'Moist, acidic soil', null, '< - 6.8', null, null, 'Moist places, open or dense forest, thickets, shorelines', '8', '4061', '15.81', '160.97', 'Requires fast draining soil. Prefers shade. Likes moist soils.', null, 'Most effective way to propagate this plant is through stem cuttings (late spring) or by layering as seeds can be difficult to collect.', '2', '3', '36', '36', 'Flower, Twin', 'Longtube Twinflower', 'Linnaea borealis ssp. americana', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Linnaea+borealis+var.+longiflora', 'https://calscape.org/Linnaea-borealis-var.-longiflora-%28Twin-Flower%29', 'https://calscape.org/storage/app/media/qr/Linnaea-borealis-var.-longiflora-%28Twin-Flower%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Linum lewisii', 'Prairie Flax', '9', 'Bats, Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 3 ft', null, 'Moderate', 'Winter Deciduous', 'Blue, Lavender, White', 'Summer, Spring', null, 'Full Sun', 'Fast, Medium, Slow', 'Very Low, Low', null, 'Easy', 'Commonly Available', '<p>Combine with complementary colored annuals or other perennial herbs such as California Poppy (Eschscholzia californica), Golden Yarrow (Eriophyllum confertiflorum) and Clarkia species</p>', 'Deer resistant', 'Forest, Woodland', 'Foothill Woodland, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Tolerates cold to -20° F', null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, '5.0 - 7.0', null, null, 'Dry open ridges, slopes', '11', '15171', '3.1800000000000002', '116.06', '<p>Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 5.6-8.4. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. It requires a minimum of 10 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate shade well and prefers sun. Likes dry slopes. It likes summer water at least once per month, and at most twice per week. Does well when grown near the ocean and does okay in the desert if it gets water.</p>', null, 'For propagating by seed:  No treatment.', '24', '36', '0', '0', 'Flax, Prairie|Flax, Western Blue', 'Blue Flax,Lewis'' Flax,Western Blue Flax,Lewis Flax', 'Linum lewisii var. alpicola|Linum lewisii var. lewisii', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Linum+lewisii', 'https://calscape.org/Linum-lewisii-%28Prairie-Flax%29', 'https://calscape.org/storage/app/media/qr/Linum-lewisii-%28Prairie-Flax%29.png');
