INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lithospermum ruderale', 'Columbia Puccoon', '2', 'Butterflies, Caterpillars', 'Perennial herb', 'Mounding', '8 - 19 in', null, 'Moderate', null, 'White, Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Desert, Woodland', 'Northern Juniper Woodland, Sagebrush Scrub', null, null, 'Prefers loamy soils', null, null, null, null, 'Open, dry slopes, plains, steppe,', '2338', '7327', '8.1699999999999999', '87.909999999999997', 'Plant in loamy soils that are at least 12 inches deep, with a pH of 6-7.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lithospermum ruderale is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes dry slopes.', null, null, '8', '19', null, null, 'Puccoon, Columbia', 'Western Gromwell,Western Stoneseed', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Lithospermum+ruderale', 'https://calscape.org/Lithospermum-ruderale-%28Columbia-Puccoon%29', 'https://calscape.org/storage/app/media/qr/Lithospermum-ruderale-%28Columbia-Puccoon%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lobelia cardinalis', 'Cardinal Flower', '1', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Upright, Spreading, Upright Columnar', '3 - 6 ft', '2 - 5 ft', 'Fast, Moderate', 'Evergreen', 'Red', 'Summer', null, 'Deep Shade, Partial Shade, Full Sun', 'Slow, Standing', 'Moderate, High', 'Keep moist', 'Moderate', 'Commonly Available', null, 'Water features or wet habitats, Deer resistant', 'Chaparral, Coastal Scrub, Wetland/Riparian', 'Bogs, Chaparral, Coastal Sage Scrub, Freshwater Marsh, Riparian Woodland, Wetland-Riparian', 'Tolerates cold to freezing&deg; F', null, 'Moist, rich soils', 'Loam, Sandy Loam', '4.0 - 8.0', null, 'Deep Organic,Organic with Rocks', 'Stream bottoms, riparian, bogs, seeps', '1136', '5988', '3.8100000000000001', '51.670000000000002', 'Plant in loamy soils that are at least 12 inches deep, with a pH of 5.8-7.8. It tolerates calcareous and infertile soils. This plant likes lots of water, requiring a minimum of 28 inches of water per year. It is tolerant of seasonal flooding. It is happy in full sun, part shade or full shade, as long as it gets plenty of water. Likes stream bottoms and seeps and even tolerates soil with no drainage. If not planted near a water source or in a year round wet area, in needs regular irrigation.', null, 'Mainly pollinated by ruby-throated hummingbirds. Proposed by seed and small volunteers around the main plant. Tolerates potting..&nbsp;&nbsp;For propagating by seed:  No treatment.', '36', '72', '24', '60', null, 'Cardinalflower', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Lobelia+cardinalis', 'https://calscape.org/Lobelia-cardinalis-%28Cardinal-Flower%29', 'https://calscape.org/storage/app/media/qr/Lobelia-cardinalis-%28Cardinal-Flower%29.png');
