INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lomatium macrocarpum', 'Bigseed Biscuitroot', '4', 'Butterflies, Caterpillars', 'Perennial herb', 'Spreading', '6 - 19 in', null, 'Moderate', null, 'White, Yellow, Purple', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, 'Moderate', 'Rarely Available', null, null, 'Desert, Forest, Woodland', 'Northern Oak Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', null, null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, 'Rocky slopes, woodlands', '2', '9394', '5.7000000000000002', '160.97', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 6-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lomatium macrocarpum is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes rocky slopes.', null, null, '6', '19', null, null, 'Biscuitroot, Bigseed', 'Large-fruited Lomatium', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Lomatium+macrocarpum', 'https://calscape.org/Lomatium-macrocarpum-%28Bigseed-Biscuitroot%29', 'https://calscape.org/storage/app/media/qr/Lomatium-macrocarpum-%28Bigseed-Biscuitroot%29.png');
