INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Lomatium triternatum', 'Lewis'' Lomatium', '3', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 3 ft', null, 'Moderate', null, 'Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Desert, Forest, Woodland', 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', null, null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, 'Open slopes, meadows, open places', '460', '8613', '6.2800000000000002', '160.97', 'Plant in sandy or loamy soils that are at least 20 inches deep, with a pH of 6.5-8.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lomatium triternatum is only slightly drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 20 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade. Likes slopes.', null, null, '24', '36', null, null, 'Lomatium, Lewis''', 'Lomatium,Nineleaf Biscuitroot', null, 'Uncommon', 'N', 'https://ucjeps.