INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Osmorhiza depauperata', 'Bluntseed Sweetroot', '1', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 3 ft', null, 'Moderate', null, 'White', 'Spring', null, 'Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Forest', 'Yellow Pine Forest', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, null, '4682', '6887', '13.08', '40.789999999999999', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 5-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Osmorhiza depauperata is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 55 inches of water per year once established. It is very tolerant of shade. Prefers part shade.', null, null, '24', '36', null, null, 'Sweetroot, Bluntseed', 'Little Sweet Cicely', null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Osmorhiza+depauperata', 'https://calscape.org/Osmorhiza-depauperata-%28Bluntseed-Sweetroot%29', 'https://calscape.org/storage/app/media/qr/Osmorhiza-depauperata-%28Bluntseed-Sweetroot%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Osmorhiza occidentalis', 'Mountain Sweet Cicely', '2', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 4 ft', null, 'Slow', null, 'Yellow', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, null, 'Never or Almost Never Available', null, null, 'Forest', 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', null, null, 'Adaptable, tolerant of sand, loam and clay', null, null, null, null, null, '802', '11503', '9.3399999999999999', '156.47', 'Plant in sandy, loamy or clay soils that are at least 16 inches deep, with a pH of 5.2-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Osmorhiza occidentalis is extremely drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 35 inches of water per year once established. It is very tolerant of shade. Prefers sun or part shade.', null, 'For propagating by seed:  2 mos. stratification (Emery and Frey 1971).', '24', '48', null, null, 'Cicely, Mountain Sweet', 'Western Sweetroot,Sweetanise', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?n