INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Pedicularis groenlandica', 'Elephant Heads', '3', 'Butterflies, Caterpillars', 'Perennial herb', 'Upright', '1 - 3 ft', null, 'Moderate', null, 'Purple, Pink, White', 'Spring', null, 'Full Sun', 'Standing', null, null, null, 'Rarely Available', null, null, 'Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian', null, null, 'Prefers loamy soils', null, null, null, null, 'Wet meadows, streamsides, bogs', '4083', '12788', '6.0899999999999999', '156.47', 'Plant in loamy soils that are at least 8 inches deep, with a pH of 5.8-7.2. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Pedicularis groenlandica is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers sun or part shade.', null, null, '12', '36', null, null, null, 'Elephant-head Lousewort,Elephanthead Lousewort,Elephant''s Head', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Pedicularis+groenlandica', 'https://calscape.org/Pedicularis-groenlandica-%28Elephant-Heads%29', 'https://calscape.org/storage/app/media/qr/Pedicularis-groenlandica-%28Elephant-Heads%29.png');
