eatment.', '8', '28', null, null, 'Penstemon, Azure', null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+azureus', 'https://calscape.org/Penstemon-azureus-%28Azure-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-azureus-%28Azure-Penstemon%29.png');
