land Beardtongue', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+deustus', 'https://calscape.org/Penstemon-deustus-%28Scabland-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-deustus-%28Scabland-Penstemon%29.png');
