INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon laetus', 'Mountain Blue Penstemon', '16', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Upright', '2 ft', '2 ft', 'Fast, Moderate', null, 'Blue, Lavender, Purple, White', 'Spring', 'Slight', 'Full Sun, Partial Shade', 'Fast, Medium', null, 'Max 1x / month once established', 'Moderate', 'Rarely Available', 'Use with mountain species such as Bush Chinquapin (Chrysolepis sempervirens), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Bitter Cherry (Prunus emarginata), Western Labrador Team (Rhododendron columbianum), and Creeping Snowberry (Symphoricarpos mollis)', 'Containers, Deer resistant', 'Chaparral, Forest, Woodland', 'Chaparral, Foothill Woodland, Red Fir Forest, Yellow Pine Forest', 'Tolerates cold to -10&deg; F', null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, '6.0 - 8.0', null, 'Organic with Rocks', 'Spring-moist places', '156', '9906', '7.5300000000000002', '160.97', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6-7.6. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Penstemon laetus is extremely drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes spring-moist soils.', null, 'For propagating by seed: No treatment; 2-3 mos. stratification may improve germination.', '24', '24', '24', '24', 'Penstemon, Gay', 'Gay Penstemon', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+laetus', 'https://calscape.org/Penstemon-laetus-%28Mountain-Blue-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-laetus-%28Mountain-Blue-Penstemon%29.png');
