INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon newberryi', 'Mountain Pride', '12', 'Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Mounding, Spreading', '5 - 12 in', '8 - 38 ft', 'Slow', null, 'Red, Pink', 'Spring', null, 'Partial Shade', 'Fast', 'Very Low', 'Max 1x / month once established', 'Moderate', 'Commonly Available', 'Sulphur Buckwheat (Eriogonum umbellatum),Common Woolly Sunflower (Eriophyllum lanatum), Antelope Bitterbrush (Purshia tridentata), Pinemat Manzanita (Arctostaphylos nevadensis), Wright''s Buckwheat (Eriogonum wrightii var subscaposum)', 'Containers, Deer resistant', 'Forest', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Tolerates cold to 0 - 10&deg; F', null, 'Rocky soils or rock ledges', null, '5 - 7', null, 'Inorganic', 'Rocky outcrops, talus', '221', '12968', '4.79', '160.97', 'Plant in sandy or loamy soils that are at least 19 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Penstemon newberryi is extremely drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 36 inches of water per year once established. It is moderately tolerant of full shade. Prefers part shade.', null, 'For propagating by seed:  2 mos. stratification (Everett 1950).', '5', '12', '96', '456', 'Penstemon, Mountain Pride', 'Mountainpride Penstemon', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+newberryi', 'https://calscape.org/Penstemon-newberryi-%28Mountain-Pride%29', 'https://calscape.org/storage/app/media/qr/Penstemon-newberryi-%28Mountain-Pride%29.png');
