INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon palmeri', 'Palmer''s Penstemon', '7', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Upright', '4 - 7 ft', '2 ft', 'Moderate', 'Evergreen, Summer Semi-deciduous', 'Purple, Blue, Pink', 'Spring', 'Pleasant', 'Full Sun, Partial Shade', 'Fast', 'Low, Very Low', 'Max 1x / month once established', 'Moderate', 'Commonly Available', 'Use with other high desert plants such as Joshua Tree (Yucca brevifolia), Pinyon Pine (Pinus edulis or monophylla), Utah Agave (Agave utahensis), Bigberry Manzanity (Arctostaphylos glauca), Big Sagebrush (Artemisia tridentata), Desert Ceanothus (Ceanothus greggii), Desert Willow (Chilpsis linearis), Mormon Tea (<a href="/search/?plant=Ephedra%20(Genus)">Ephedra spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Apache Plume (Fallugia paradoxa), Chaparral Yucca (Hesperoyucca whipplei), California Juniper (Juniperus californica), Bladderpod (Peritoma arborea), Antelope Brush (Purshia tridentata), Sage (Salvia dorrii or mohavensis), Jojoba (Simmondsia chinensis), Banana Yucca (Yucca baccata), and various cactus species.', 'Deer resistant', 'Desert, Woodland', 'Joshua Tree Woodland, Pinyon-Juniper Woodland', 'Tolerates cold to -5&deg; F', null, 'Typically sandy or decomposed granite', null, '6.0 - 8.0', null, 'Inorganic', 'Slopes washes, canyons and alluvial fans of desert mountains', '2593', '8301', '3.2400000000000002', '19.559999999999999', 'Prefers sun or part shade. Likes sandy soils .  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'For propagating by seed:  1-3 mos. stratification.', '48', '84', '24', '24', 'Penstemon, Palmer''s', 'Palmer Penstemon', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+palmeri', 'https://calscape.org/Penstemon-palmeri-%28Palmer%27s-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-palmeri-%28Palmer%27s-Penstemon%29.png');
