INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon rydbergii', 'Rydberg''s Penstemon', '13', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Upright', '1 - 3 ft', '3 ft', 'Moderate', 'Winter Deciduous', 'Blue, Lavender, Purple', 'Summer', null, 'Full Sun, Partial Shade', 'Slow', 'Moderate, High', 'Keep moist', null, 'Commonly Available', 'Use in a mountain meadow garden with native grasses and perennials such as Sitka Columbine (Aquilegia formosa), Sierra Mariposa Lily (Calochortus minimus), Roundleaf Sundew (Drosera rotundifolia), Western Blue Flag (Iris missouriensis), Alpine Lily (Lilium parvum), Bog Orchid (Platanthera sparsiflora), Buttercup (<a href="/search/?plant=Ranunculus%20(Genus)">Ranunculus spp.</a>), <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a>, and Violet (<a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>)', 'Containers, Deer resistant', 'Desert, Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to -15&deg; F', null, 'Tolerates a variety of soils', null, '5.0 - 6.8', null, null, 'Moist meadows and streambanks of the Sierras', '859', '12391', '4.79', '115.66', 'Plant in loamy or clay soils that are at least 14 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Penstemon rydbergii is only slightly drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It does not tolerate full shade well. Prefers sun or part shade.', null, 'For propagating by seed:  2 mos. stratification (Williams 1986).', '12', '36', '36', '36', 'Penstemon, Rydberg''s', 'Rydberg Penstemon,Meadow Beardtongue', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+rydbergii', 'https://calscape.org/Penstemon-rydbergii-%28Rydberg%27s-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-rydbergii-%28Rydberg%27s-Penstemon%29.png');
