INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon speciosus', 'Royal Penstemon', '17', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Upright', '2 ft', '2 ft', 'Fast, Moderate', null, 'Blue, Lavender, Purple', 'Summer, Spring', null, 'Full Sun, Partial Shade', 'Fast', 'Very Low', 'Max 2x / month once established', 'Moderate', 'Commonly Available', 'Trees - Joshua Tree (Yucca brevifolia), Pinyon Pine (Pinus monophylla), Juniper (<a href="/search/?plant=Juniperus%20(Genus)">Juniperus spp.</a>), Red Fir (Abies magnifica), Ponderosa Pine (Pinus ponderosa)<br/>Shrubs and herbs - Big Sagebrush (Artemisia tridentata), Sulphur Buckwheat (Eriogonum umbellatum), Blue Flax (Linum lewisii), Scarlet Gilia (Ipomopsis aggregata), and Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>)', 'Containers', 'Desert, Forest, Woodland', 'Joshua Tree Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Tolerates cold to 0&deg; F', '1, 2, 3, 7, 14, 15, 16', 'Tolerant of a variety of soils as long as adequate drainage is provided', null, '6.0 - 8.0', null, 'Inorganic,Organic with Rocks', 'Sagebrush scrub, sub-alpine mountain forests (fir or pine), primarily inland mountain or foothill areas that experience hot summers and cold winters, such as the Owen''s Valley and Modoc Plateau', '1219', '13115', '3.9399999999999999', '115.09', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6.4-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile and clay rich soils. It requires a minimum of 8 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil and does not tolerate full shade well. Prefers sun or part shade.', null, 'For propagating by seed:  1-2 mos. stratification.', '24', '24', '24', '24', 'Penstemon, Royal', 'Royal Beardtongue,Showy Penstemon', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+speciosus', 'https://calscape.org/Penstemon-speciosus-%28Royal-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-speciosus-%28Royal-Penstemon%29.png');
