INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Penstemon spectabilis', 'Showy Penstemon', '13', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Perennial herb', 'Mounding, Upright Columnar', '2 - 4 ft', '3 - 4 ft', 'Moderate', 'Evergreen', 'Blue, Pink, Purple', 'Spring, Winter', 'None', 'Full Sun', 'Fast', 'Very Low', 'Max 1x / month once established', 'Moderate', 'Commonly Available', 'Sagebrush (Artemisia californica), San Diego Viguiera (Bahiopsis laciniata), California Encelia (Encelia californica), Buckwheat (Eriogonum fasciculatum), <a href="/search/?plant=Manzanita%20(Genus)">Manzanita spp.</a>, scrub oaks, and various annuals such as California Poppy.', 'Containers, Deer resistant', 'Chaparral, Coastal Scrub', 'Chaparral, Coastal Sage Scrub', 'Tolerates cold to 0&deg; F', null, 'Performs best and lives longest in well-drained soil', null, '6.0 - 7.5', null, 'Organic with Rocks', 'Gentle rocky slopes and dry flats as part of chaparral or coastal sage scrub', '9', '7134', '1.8999999999999999', '51.670000000000002', 'Prefers sun or part shade. Likes gravelly or sandy slopes, dry creek beds, and sandy soils. Will tolerate clay soils. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils, but can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.<br/>', null, 'For propagating by seed:  No treatment.', '24', '48', '36', '48', null, null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Penstemon+spectabilis', 'https://calscape.org/Penstemon-spectabilis-%28Showy-Penstemon%29', 'https://calscape.org/storage/app/media/qr/Penstemon-spectabilis-%28Showy-Penstemon%29.png');
