INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Phlox diffusa', 'Spreading Phlox', '7', 'Butterflies, Caterpillars', 'Perennial herb', 'Mounding', '6 in', null, 'Slow', null, 'Purple, White', 'Spring', null, 'Full Sun', null, null, null, null, null, null, null, 'Forest, Meadow', 'Alpine Fell-Fields, Douglas-Fir Forest, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', null, '1, 2, 3, 4, 5, 6, 7, 14, 15, 16, 17, 18, 19, 20, 21', 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, 'Dry open places', '559', '12966', '6.0899999999999999', '160.97', 'Plant in sandy or loamy soils that are at least 15 inches deep, with a pH of 6.5-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Phlox diffusa is extremely drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 40 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers sun.', null, null, '6', '6', null, null, 'Phlox, Spreading', null, null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Phlox+diffusa', 'https://calscape.org/Phlox-diffusa-%28Spreading-Phlox%29', 'https://calscape.org/storage/app/media/qr/Phlox-diffusa-%28Spreading-Phlox%29.png');
