INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Prunella vulgaris', 'Common Selfheal', '0', null, 'Perennial herb', 'Mounding, Spreading, Upright', '1 - 2 ft', '6 - 9 in', 'Fast', null, 'Purple, Pink', 'Summer', 'Pleasant', 'Full Sun, Partial Shade', 'Fast, Medium', 'Moderate', 'Keep moist', 'Easy', 'Commonly Available', 'Ocean spray (Holodiscus discolor), willows (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), Pacific Ninebark (Physocarpus capitatus), Blue wildrye (Elymus glaucus).', 'Containers, Deer resistant, Groundcover, Lawn alternative', 'Wetland/Riparian', 'Weed (disturbed places), Wetland-Riparian', 'Tolerates cold to -5&deg; F', null, 'Prefers damp sandy loam', 'Clay, Loam, Sand', '6.1 - 7.8', null, null, 'Found in a variety of places, including forest edges, meadows, and vernal wetlands.', '2', '11269', '6.1600000000000001', '167.94', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 5.4-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Prunella vulgaris is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.', 'Selfheal is generally impervious to most pests, but beware of predation by slugs and snails on young plants.', 'Can be propagated by seed (no treatment necessary), by plant divisions, or by planting stolons. Stolon propogation yields larger plants in a shorter amount of time. Collect seeds from the flowering heads at the end of the growing season.', '12', '24', '6', '9', 'Selfheal, Common', 'Selfheal,Self-heal', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Prunella+vulgaris', 'https://calscape.org/Prunella-vulgaris-%28Common-Selfheal%29', 'https://calscape.org/storage/app/media/qr/Prunella-vulgaris-%28Common-Selfheal%29.png');
