INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Rubus parviflorus', 'Thimbleberry', '72', 'Bats, Butterflies, Caterpillars', 'Shrub, Perennial herb', 'Upright, Spreading', '4 - 8 ft', null, 'Moderate, Fast', 'Winter Deciduous', 'White, Yellow', 'Spring', 'Pleasant', 'Partial Shade', 'Fast', 'Low, Moderate', 'Max 1x / month once established', 'Easy', null, 'Use with trees from its native range, such as Fir (<a href="/search/?plant=Abies%20(Genus)">Abies spp.</a>), Pine (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), and Redwood (Sequoia sempervirens)', 'Containers, Hedge', 'Forest, Wetland/Riparian', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Red Fir Forest, Forest, Yellow Pine Forest, Wetland-Riparian', 'Tolerates cold to -10&deg; F', '1, 2, 4*, 5*, 6*, 7*, 14, 15*, 16*, 17*, 18', 'Prefers moist, fertile soil with good drainage', null, '5.0 - 7.0', null, null, 'Shaded, moist areas on the edge of woodland or forest, often in mountains', '0', '11401', '4.79', '167.94', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 4.8-7.2. It is intolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Rubus parviflorus is moderately drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 45 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade.', 'Prune in winter to control height and/or spread', 'For propagating by seed:  3 mos. stratification may give satisfactory germination. Soaking in either 1% sodium hypochlorite (household bleach) 7 days or concentrated H2S04 20-60 mins., then 3 mos. warm and 3 mos. cold stratification may improve germination (USDA Forest Service 1974). Easily propagated from stem cuttings.', '48', '96', null, null, 'Thimbleberry, Western', 'Thimbleberry', 'Rubus parviflorus var. velutinus', null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Rubus+parviflorus', 'https://calscape.org/Rubus-parviflorus-%28Thimbleberry%29', 'https://calscape.org/storage/app/media/qr/Rubus-parviflorus-%28Thimbleberry%29.png');
