INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Sidalcea neomexicana', 'Salt Spring Checkerbloom', '6', 'Birds, Butterflies, Caterpillars', 'Perennial herb', 'Upright', '2 - 3 ft', null, 'Moderate', 'Winter Deciduous', 'Purple, Pink', 'Spring', null, 'Full Sun', 'Standing', 'Moderate', null, null, 'Rarely Available', null, null, 'Chaparral, Coastal Scrub, Desert, Forest, Wetland/Riparian', 'Alkali Sink, Chaparral, Coastal Sage Scrub, Creosote Bush Scrub, Yellow Pine Forest, Wetland-Riparian', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, 'Alkaline springs and marshes', '27', '8698', '3.27', '53.32', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 6.2-7.8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Sidalcea neomexicana is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 28 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, null, '24', '36', null, null, 'Checkerbloom, Salt Spring', null, null, 'Rare', 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Sidalcea+neomexicana', 'https://calscape.org/Sidalcea-neomexicana-%28Salt-Spring-Checkerbloom%29', 'https://calscape.org/storage/app/media/qr/Sidalcea-neomexicana-%28Salt-Spring-Checkerbloom%29.png');
