INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Veronica wormskjoldii', 'Alpine Speedwell', '2', 'Butterflies, Caterpillars', 'Perennial herb', 'Mounding', '10 - 16 in', null, 'Moderate', null, 'Blue', 'Summer', null, 'Partial Shade', null, 'Moderate', null, null, 'Never or Almost Never Available', null, null, 'Forest, Wetland/Riparian', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian', null, null, 'Prefers loamy or clay soils.  Grows poorly in sandy soils.', null, null, null, null, 'Moist places', '1220', '3832', '4.79', '129.88', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 6-7.3. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Veronica wormskjoldii is only slightly drought tolerant. It requires a minimum of 32 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers part shade.', null, null, '10', '16', null, null, 'Speedwell, Alpine', 'American Alpine Speedwell', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Veronica+wormskjoldii', 'https://calscape.org/Veronica-wormskjoldii-%28Alpine-Speedwell%29', 'https://calscape.org/storage/app/media/qr/Veronica-wormskjoldii-%28Alpine-Speedwell%29.png');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Butterflies and Moths Supported", "Attracts Wildlife", "Plant Type", "Form", "Height", "Width", "Growth Rate", "Seasonality", "Flower Color", "Flowering Season", "Fragrance", "Sun", "Soil Drainage", "Water Requirement", "Summer Irrigation", "Ease of Care", "Nursery Availability", "Companions", "Special Uses", "Communities (simplified)", "Communities", "Hardiness", "Sunset Zones", "Soil", "Soil Texture", "Soil pH", "Soil Toxicity", "Mulch", "Site Type", "Elevation (min)", "Elevation (max)", "Rainfall (min)", "Rainfall (max)", "Tips", "Pests", "Propagation", "Height (min)", "Height (max)", "Width (min)", "Width (max)", "Other Names", "Alternative Common Names", "Obsolete Names", "Rarity", "Is Cultivar", "Jepson Link", "Plant Url", "QR Codes (change number to change image size in pixels)") VALUES ('Vicia americana', 'American Vetch', '21', 'Butterflies, Caterpillars', 'Perennial herb, Vine', 'Mounding', '1 ft', null, 'Moderate', null, 'Purple, Pink, Lavender', 'Spring', null, 'Full Sun, Partial Shade', null, null, null, 'Moderate', 'Rarely Available', null, null, 'Forest', 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest', null, null, 'Prefers sandy or loamy soils.  Does not grow well in clay soils.', null, null, null, null, null, '0', '2775', '3.52', '160.97', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 5.9-7.2. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires fertile soil. Vicia americana is extremely drought tolerant. It requires a minimum of 9 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade.', null, null, '12', '12', null, null, 'Vetch, American', 'Purple Vetch', null, null, 'N', 'https://ucjeps.berkeley.edu/eflora/eflora_display.php?name=Vicia+americana', 'https://calscape.org/Vicia-americana-%28American-Vetch%29', 'https://calscape.org/storage/app/media/qr/Vicia-americana-%28American-Vetch%29.png');
